const costSection=document.createElement('section');costSection.id='costSection';scheduleSection.after(costSection);
const costDialog=document.createElement('dialog');costDialog.id='costDialog';document.body.append(costDialog);
let costEdit=null,costKind='expense',costProject=null,costURLs=[];
const costProjectData=()=>data.projects.find(p=>p.id===selected);
function getCosts(p=costProjectData()){return p.costs||{currency:'PYG',quotes:[],expenses:[],suppliers:[],conclusion:''}}
function persistCosts(c,p=costProjectData()){const previous=p.costs;p.costs=c;try{localStorage.setItem(key,JSON.stringify(data));return true}catch{p.costs=previous;toast('No se pudo guardar. Revisa el espacio del navegador.');return false}}
function clearCostURLs(){costURLs.forEach(URL.revokeObjectURL);costURLs=[]}
function drawCosts(){clearCostURLs();const p=costProjectData();costSection.hidden=!p||projectPanel!=='costs';if(!p)return;const tabs=$('#scheduleSection .projectPanels');if(tabs&&!tabs.querySelector('[data-panel="costs"]'))tabs.insertAdjacentHTML('beforeend',`<button data-panel="costs" class="${projectPanel==='costs'?'primary':''}">Costos</button>`);if(projectPanel!=='costs')return;
 const c=getCosts(),t=costTotals(c),money=n=>costMoney(n,c.currency),quoteGroups=[...new Set(c.quotes.map(x=>x.category+'|'+x.concept.toLocaleLowerCase().trim()))];
 costSection.innerHTML=`<div class="sectionhead"><div><h2>Costos del proyecto</h2><p class="muted">Presupuestos, comparativos, gastos y sus comprobantes.</p></div><button class="primary" id="costPDF">↓ Cierre de gastos en PDF</button></div><div class="costBar"><label>Moneda del proyecto<select id="costCurrency">${['PYG','USD','EUR','ARS','BRL'].map(v=>`<option ${c.currency===v?'selected':''}>${v}</option>`).join('')}</select></label><span class="muted">Importes finales, con impuestos incluidos. Una moneda por proyecto.</span></div><div class="costStats">${[['Presupuesto aprobado',t.budget],['Gasto total incurrido',t.actual],['Gastos adicionales',t.additional],['Diferencia vs. presupuesto',t.variance],['Pagado',t.paid],['Pendiente de pago',t.pending]].map(([l,n])=>`<div class="stat"><label>${l}</label><strong>${money(n)}</strong></div>`).join('')}</div><p class="muted">El presupuesto suma solo las cotizaciones aprobadas: base ${money(t.base)} + adicionales ${money(t.additionalBudget)}. Los gastos incluyen pagados y pendientes; las cotizaciones no se suman al gasto.</p><div class="sectionhead costHeading"><h2>Presupuestos y comparativos</h2><button data-new-cost="quote">＋ Cotización</button></div><p class="muted">Usa el mismo concepto y tipo para comparar ofertas del mismo alcance. Aprueba una alternativa por concepto y tipo.</p>${quoteGroups.map(g=>{const rows=c.quotes.filter(x=>x.category+'|'+x.concept.toLocaleLowerCase().trim()===g).sort((a,b)=>a.amount-b.amount),min=rows[0].amount;return `<div class="costCompare"><h3>${esc(rows[0].concept)} <small>${esc(rows[0].category)}</small></h3><div class="costTableWrap"><table class="costTable"><thead><tr><th>Proveedor</th><th>Fecha</th><th>Oferta</th><th>Estado</th><th>Gestionar</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.supplier||'Sin proveedor')}</td><td>${date(x.date)}</td><td>${money(x.amount)} ${rows.length>1&&x.amount===min?'<span class="badge">Menor oferta</span>':''}</td><td>${x.approved?'Aprobado':'Alternativa'}</td><td><button data-edit-quote="${x.id}">Editar / adjuntos</button><button data-approve="${x.id}">${x.approved?'Quitar aprobación':'Aprobar'}</button></td></tr>`).join('')}</tbody></table></div></div>`}).join('')||'<p class="empty">Registra las ofertas de tus proveedores para compararlas.</p>'}<div class="sectionhead costHeading"><h2>Gastos incurridos</h2><button data-new-cost="expense">＋ Registrar gasto</button></div><div class="costTableWrap"><table class="costTable"><thead><tr><th>Concepto / Tipo</th><th>Proveedor</th><th>Fecha</th><th>Importe</th><th>Pago</th><th>Factura</th><th>Gestionar</th></tr></thead><tbody>${c.expenses.map(x=>`<tr><td>${esc(x.concept)}<small>${esc(x.category)}</small></td><td>${esc(x.supplier||'Sin proveedor')}</td><td>${date(x.date)}</td><td>${money(x.amount)}</td><td>${esc(x.status)}</td><td>${esc(x.invoice||'Sin número')}<small data-invoice-count="${x.id}">Consultando adjuntos…</small></td><td><button data-edit-expense="${x.id}">Editar / facturas</button></td></tr>`).join('')||'<tr><td colspan="7" class="empty">Todavía no hay gastos registrados.</td></tr>'}</tbody></table></div><div class="sectionhead costHeading"><h2>Proveedores</h2><button data-new-cost="supplier">＋ Proveedor</button></div><div class="costSuppliers">${c.suppliers.map(x=>`<article class="costCompare"><b>${esc(x.name)}</b><p class="muted">RUC / ID: ${esc(x.taxId||'Sin dato')}<br>${esc(x.contact||'Sin contacto')}</p><button data-edit-supplier="${x.id}">Editar proveedor</button></article>`).join('')||'<p class="empty">Crea tu directorio de proveedores.</p>'}</div><div class="costHeading"><h2>Conclusión del proyecto</h2><p class="muted">Añade las causas de los adicionales, acuerdos y observaciones finales. Se incluirán en el PDF junto con el detalle económico.</p><textarea id="costConclusion" maxlength="5000" rows="4" placeholder="Conclusión y observaciones del cierre…">${esc(c.conclusion)}</textarea><button id="saveCostConclusion">Guardar conclusión</button><p class="muted">Los datos y facturas se guardan en este navegador y dispositivo. El PDF lista las facturas; los archivos se descargan desde cada gasto.</p></div>`;
 const pid=p.id;evidenceStore('readonly',s=>s.getAll()).then(files=>{if(selected!==pid||projectPanel!=='costs')return;$$('[data-invoice-count]').forEach(el=>{const n=files.filter(f=>f.costProjectId===pid&&f.costType==='expense'&&f.costEntryId===el.dataset.invoiceCount).length;el.textContent=n?n+' archivo(s) adjunto(s)':'Sin factura adjunta'})}).catch(()=>$$('[data-invoice-count]').forEach(el=>el.textContent='Adjuntos no disponibles'));
}
const scheduleDrawBeforeCosts=drawSchedule;drawSchedule=function(){scheduleDrawBeforeCosts();drawCosts()};drawSchedule();
function costOpen(kind,id){costKind=kind;costEdit=id||null;costProject=selected;clearCostURLs();const c=getCosts(),arr=kind==='supplier'?c.suppliers:kind==='quote'?c.quotes:c.expenses,x=arr.find(x=>x.id===id)||{},supplier=kind==='supplier';
costDialog.innerHTML=`<form id="costForm"><div class="sectionhead"><h2>${id?'Editar':'Nuevo'} ${supplier?'proveedor':kind==='quote'?'presupuesto':'gasto'}</h2><button type="button" id="closeCost">✕</button></div>${supplier?`<label>Nombre del proveedor<input name="name" required maxlength="120" value="${esc(x.name)}"></label><label>RUC / Identificación<input name="taxId" maxlength="60" value="${esc(x.taxId)}"></label><label>Contacto (teléfono o correo)<input name="contact" maxlength="160" value="${esc(x.contact)}"></label>`:`<label>Concepto<input name="concept" required maxlength="160" list="costConcepts" value="${esc(x.concept)}"></label><datalist id="costConcepts">${[...new Set(c.quotes.map(x=>x.concept))].map(n=>`<option value="${esc(n)}">`).join('')}</datalist><label>Proveedor<input name="supplier" required maxlength="120" list="costSupplierNames" value="${esc(x.supplier)}"></label><datalist id="costSupplierNames">${[...new Set([...c.suppliers.map(x=>x.name),...c.quotes.map(x=>x.supplier),...c.expenses.map(x=>x.supplier)])].map(n=>`<option value="${esc(n)}">`).join('')}</datalist><div class="formrow"><label>Importe final (${c.currency})<input name="amount" type="number" required min="0.01" max="1000000000000" step="0.01" value="${x.amount||''}"></label><label>Fecha<input name="date" type="date" required value="${esc(x.date||new Date().toLocaleDateString('en-CA'))}"></label></div><label>Tipo<select name="category"><option ${x.category!=='Adicional'?'selected':''}>Base</option><option ${x.category==='Adicional'?'selected':''}>Adicional</option></select></label>${kind==='expense'?`<label>Estado del pago<select name="status"><option ${x.status!=='Pagado'?'selected':''}>Pendiente</option><option ${x.status==='Pagado'?'selected':''}>Pagado</option></select></label><label>Número de factura<input name="invoice" maxlength="80" value="${esc(x.invoice)}"></label>`:'<p class="muted">La aprobación se gestiona en el comparativo del proyecto.</p>'}<label>Notas / alcance / justificación<textarea name="notes" maxlength="2000" rows="3">${esc(x.notes)}</textarea></label>`}<div class="dialogfoot"><button type="button" id="deleteCost" class="danger" ${id?'':'hidden'}>Eliminar</button><button class="primary" type="submit">Guardar</button></div></form>${supplier?'':`<section class="costAttachments"><h3>${kind==='expense'?'Facturas y comprobantes':'Documentos del presupuesto'}</h3><div id="costAttachments">${id?'Cargando archivos…':'Guarda el registro para adjuntar archivos.'}</div></section>`}`;
$('#closeCost').onclick=()=>costDialog.close();$('#costForm').onsubmit=costSubmit;$('#deleteCost').onclick=deleteCost;costDialog.showModal();if(id&&!supplier)loadCostAttachments();}
function costSubmit(e){e.preventDefault();const p=data.projects.find(p=>p.id===costProject),c=structuredClone(getCosts(p)),f=$('#costForm').elements,supplier=costKind==='supplier',arr=supplier?c.suppliers:costKind==='quote'?c.quotes:c.expenses;let x=arr.find(x=>x.id===costEdit)||{id:crypto.randomUUID(),approved:false};const fields=supplier?['name','taxId','contact']:['concept','supplier','date','category','notes',...(costKind==='expense'?['status','invoice']:[])];for(const field of fields){x[field]=f[field].value.trim()}if(!(supplier?x.name:x.concept&&x.supplier)){toast('Completa los campos obligatorios');return}if(!supplier){x.amount=Math.round(Number(f.amount.value)*100)/100;if(!Number.isFinite(x.amount)||x.amount<=0||x.amount>1e12)return;if(costKind==='quote'&&x.approved&&c.quotes.some(q=>q.id!==x.id&&q.approved&&q.category===x.category&&q.concept.toLowerCase()===x.concept.toLowerCase())){toast('Ya existe una oferta aprobada para ese concepto. Quita su aprobación antes de continuar.');return}}if(!costEdit)arr.push(x);if(!persistCosts(c,p))return;toast('Registro guardado');const id=x.id;costDialog.close();drawCosts();if(!supplier)costOpen(costKind,id)}
async function deleteCost(){if(!confirm('¿Eliminar este registro y sus archivos adjuntos?'))return;const p=data.projects.find(p=>p.id===costProject),c=structuredClone(getCosts(p)),key=costKind==='supplier'?'suppliers':costKind==='quote'?'quotes':'expenses';c[key]=c[key].filter(x=>x.id!==costEdit);if(!persistCosts(c,p))return;try{const files=await evidenceStore('readonly',s=>s.getAll());for(const f of files.filter(f=>f.costProjectId===costProject&&f.costType===costKind&&f.costEntryId===costEdit))await evidenceStore('readwrite',s=>s.delete(f.id))}catch{toast('Registro eliminado; no se pudieron limpiar sus archivos locales.')}costDialog.close();drawCosts()}
async function loadCostAttachments(){const pid=costProject,id=costEdit,type=costKind;try{const files=(await evidenceStore('readonly',s=>s.getAll())).filter(f=>f.costProjectId===pid&&f.costEntryId===id&&f.costType===type);if(!costDialog.open||costProject!==pid||costEdit!==id)return;clearCostURLs();const el=$('#costAttachments');el.innerHTML='<label>Adjuntar PDF o imagen (máximo 25 MB por archivo)<input type="file" id="costFiles" multiple accept="application/pdf,image/jpeg,image/png,image/webp"></label><div id="costFileList"></div>';for(const f of files){const url=URL.createObjectURL(f.blob);costURLs.push(url);const item=document.createElement('div');item.className='costFile';item.innerHTML=`<span>${esc(f.name)}</span><small>${(f.blob.size/1024/1024).toFixed(2)} MB</small><button type="button" data-remove-cost-file="${f.id}">Eliminar</button>`;if(/^image\/(jpeg|png|webp)$/.test(f.type)){const img=document.createElement('img');img.src=url;img.alt=f.name;item.append(img)}const a=document.createElement('a');a.href=url;a.download=f.name;a.textContent='↓ Descargar';item.append(a);$('#costFileList').append(item)}if(!files.length)$('#costFileList').innerHTML='<p class="muted">Sin archivos adjuntos.</p>';
 $('#costFiles').onchange=async e=>{e.target.disabled=true;try{for(const f of e.target.files){if(!['application/pdf','image/jpeg','image/png','image/webp'].includes(f.type))throw new Error('Usa archivos PDF, JPG, PNG o WEBP.');if(f.size>25*1024*1024)throw new Error('Cada archivo debe pesar como máximo 25 MB.');await evidenceStore('readwrite',s=>s.put({id:crypto.randomUUID(),costProjectId:pid,costEntryId:id,costType:type,name:f.name,type:f.type,created:Date.now(),blob:f}))}toast('Archivos guardados');loadCostAttachments();drawCosts()}catch(err){toast(err.message||'No se pudieron guardar los archivos');loadCostAttachments()}};
 $('#costFileList').onclick=async e=>{const b=e.target.closest('[data-remove-cost-file]');if(!b||!confirm('¿Eliminar este archivo adjunto?'))return;try{await evidenceStore('readwrite',s=>s.delete(b.dataset.removeCostFile));loadCostAttachments();drawCosts()}catch{toast('No se pudo eliminar el archivo')}};
 }catch{if($('#costAttachments'))$('#costAttachments').textContent='No se pudo acceder a los adjuntos. Comprueba el almacenamiento del navegador.'}}
costDialog.addEventListener('close',clearCostURLs);
costSection.addEventListener('change',e=>{if(e.target.id!=='costCurrency')return;const c=structuredClone(getCosts());if((c.quotes.length||c.expenses.length)&&!confirm('Cambiar la moneda cambia la etiqueta de todos los importes, sin convertirlos. ¿Continuar?')){e.target.value=c.currency;return}c.currency=e.target.value;if(persistCosts(c))drawCosts()});
costSection.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.newCost){costOpen(b.dataset.newCost);return}for(const type of ['quote','expense','supplier']){const id=b.getAttribute('data-edit-'+type);if(id){costOpen(type,id);return}}if(b.dataset.approve){const c=structuredClone(getCosts()),q=c.quotes.find(x=>x.id===b.dataset.approve);if(!q.approved){const other=c.quotes.find(x=>x.id!==q.id&&x.approved&&x.category===q.category&&x.concept.toLowerCase().trim()===q.concept.toLowerCase().trim());if(other&&!confirm('Esto reemplazará la aprobación de '+other.supplier+'. ¿Continuar?'))return;if(other)other.approved=false}q.approved=!q.approved;if(persistCosts(c))drawCosts();return}if(b.id==='saveCostConclusion'){const c=structuredClone(getCosts());c.conclusion=$('#costConclusion').value.trim();if(persistCosts(c))toast('Conclusión guardada');return}if(b.id==='costPDF'){b.disabled=true;try{const p=costProjectData(),c=structuredClone(getCosts(p));c.conclusion=$('#costConclusion').value.trim();if(!persistCosts(c,p))return;const files=await evidenceStore('readonly',s=>s.getAll()),bytes=costsPDF(p,c,files.filter(f=>f.costProjectId===p.id)),url=URL.createObjectURL(new Blob([bytes],{type:'application/pdf'})),a=document.createElement('a');a.href=url;a.download='cierre-costos-'+p.name.replace(/[^\p{L}\p{N}-]/gu,'-')+'.pdf';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('Informe PDF exportado')}catch{toast('No se pudo exportar el informe. Comprueba el acceso a los archivos locales.')}finally{b.disabled=false}}});

